from decimal import Decimal, ROUND_HALF_UP, InvalidOperation
def calc_total(items: list[dict]) -> str:
    """
    Calculate the total price of items in the cart.

    :param items: List of items, each with 'price' (nonnegative finite decimal string) and 'qty' (nonnegative int).
    :return: The sum of all item prices, rounded to 2 decimals with ROUND_HALF_UP. Empty list returns '0.00'.
    :raises ValueError: If any item has an invalid price or qty.
    """
    if not items:
        return '0.00'

    total = Decimal('0')
    for item in items:
        if not isinstance(item['price'], str) or not isinstance(item['qty'], int):
            raise ValueError('Invalid price or quantity.')
        try:
            price = Decimal(item['price'])
        except InvalidOperation:
            raise ValueError('Invalid price format.')

        if price < 0 or item['qty'] < 0:
            raise ValueError('Price and quantity must be nonnegative.')

        total += price * item['qty']

    return str(total.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP))

from decimal import Decimal, ROUND_HALF_UP

def apply_discount(amount: str, rate: str) -> str:
    if not (0 <= Decimal(rate) <= 1):
        raise ValueError('Rate must be a fraction between 0 and 1 inclusive.')
    if Decimal(amount) < 0:
        raise ValueError('Amount must be nonnegative.')
    try:
        discounted_amount = Decimal(amount) * (1 - Decimal(rate))
    except Exception as e:
        raise ValueError('Invalid input: ' + str(e))
    return str(discounted_amount.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP))

