def paginate(items: list, page: int, size: int) -> dict:
    if not isinstance(page, int) or not isinstance(size, int):
        raise ValueError('page and size must be integers')
    if isinstance(page, bool) or isinstance(size, bool):
        raise ValueError('page and size must be integers')
    if not (1 <= size <= 100):
        raise ValueError('size must be between 1 and 100')
    if page < 1:
        raise ValueError('page must be at least 1')
    total = len(items)
    pages = math.ceil(total / size) if total > 0 else 0
    start = (page - 1) * size
    end = start + size
    paged_items = items[start:end] if 0 <= start < total else []
    return {'items': paged_items, 'total': total, 'pages': pages}

