from pydantic import BaseModel, conint, confloat
from decimal import Decimal, ROUND_HALF_UP

app = FastAPI()

class QuoteRequest(BaseModel):
    unitPrice: confloat(ge=0, finite=True)
    quantity: conint(gt=0, lt=101)

@app.post('/quote')
async def quote(request: QuoteRequest):
    total = (Decimal(request.unitPrice) * request.quantity).quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
    return {'total': str(total)}

